script:
const cp = require('child_process');
const path = require('path');

const BAT_PATH = path.join('C:', 'Codes', 'audiobook', 'start_neurolink_server.bat');
// 改这个字符串就必须同时改 start_neurolink_server.bat 里的 `title` 那一行
const WINDOW_TITLE = 'Neurolink TTS Server';

let fileSeq = 0;

const sleep = (ms) => new Promise(resolve => setTimeout(resolve, ms));

// 服务端是在模块导入阶段把模型全部加载完之后才开始监听端口的，
// 所以端口一旦连得上就说明模型已就绪 —— 直接拿它当就绪信号。
const probe = async(axios, baseUrl) => {
    try {
        const res = await axios.get(baseUrl, { timeout: 3000 });
        return { up: true, modelLoaded: !!(res.data && res.data.model_loaded) };
    } catch (e) {
        return { up: false, modelLoaded: false };
    }
};

const spawnServer = () => {
    // 使用 cmd.exe /c start "" "batPath" 强制弹出一个独立的可见 CMD 窗口
    cp.spawn('cmd.exe', ['/c', 'start', '""', BAT_PATH], {
        env: Object.assign({}, process.env, { LAUNCHED_BY_KOODO: '1' }),
        windowsHide: false,
        detached: true
    });
    // 只有我们自己拉起来的服务端才归我们收拾。Koodo 关闭时按窗口标题杀掉该窗口
    // 以及其下的所有子进程 (python server)。
    // 注意这个 hook 只在 spawnServer() 里注册：如果服务端是你手动开的，
    // 插件不会去动它，关掉 Koodo 也不会把你的窗口一起带走。
    if (!global.neurolinkKillHook) {
        global.neurolinkKillHook = true;
        process.on('exit', () => {
            try { cp.execSync('taskkill /FI "WINDOWTITLE eq ' + WINDOW_TITLE + '*" /T /F'); } catch (e) {}
        });
    }
};

// 先探测，再决定要不要拉起服务端。
//
// 这里以前是在脚本顶层无条件 spawn，只靠 `if (!global.neurolinkServer)` 挡重复，
// 而那个守卫挡不住任何真实情况：
//   1. 它存的是 `cmd /c start` 这个转发进程，毫秒级就退出了，跟服务端死活无关；
//   2. 插件脚本在新的 JS 上下文里重新求值时 global 是空的，于是又起一个；
//   3. server.py 没有 idle watchdog（audiobook/app.py 才有），上一轮 Koodo 没清
//      干净就会留下一个还占着 8002 的孤儿进程。
// 只要 8002 上已经有人（手动起的 / 上次留下的），第二个实例 uvicorn 就会
// bind 失败：[Errno 10048]，退出码 3，窗口停在 pause 上。
// 同目录的 koodo_tts_plugin.json（8000 那个）一直是先 checkServer 再 spawn 的，
// 这里补齐同样的顺序。
const ensureServer = async(axios, baseUrl) => {
    if (global.neurolinkReady) return global.neurolinkReady;

    const pending = (async() => {
        let st = await probe(axios, baseUrl);
        if (!st.up) {
            // 一个 JS 上下文里最多只 spawn 一次。冷启动慢到超过下面这个
            // deadline 时会重来一轮等待，但绝不能重来一次 spawn ——
            // 那样两个实例会同时加载模型，先绑上的赢，后一个照样 10048。
            if (!global.neurolinkSpawned) {
                global.neurolinkSpawned = true;
                console.log('Neurolink TTS: port is free, starting server...');
                spawnServer();
            }
            // GPT-SoVITS 冷启动要把 roberta / hubert / s1 / s2 全部载入显存，
            // 经常超过一分钟。
            const deadline = Date.now() + 240000;
            while (Date.now() < deadline) {
                await sleep(2000);
                st = await probe(axios, baseUrl);
                if (st.up) break;
            }
        }
        if (!st.up) {
            console.log('Neurolink TTS: server not reachable after 240s, sending request anyway.');
            return false;
        }
        if (!st.modelLoaded) {
            console.log('Neurolink TTS: server is up but model failed to load.');
            return false;
        }
        return true;
    })();

    global.neurolinkReady = pending;
    const ok = await pending;
    // 失败不缓存，否则服务端晚一点才起来就永远恢复不了（下一句会重新探测，
    // 但因为 neurolinkSpawned 已经置位，不会再多起一个实例）。
    if (!ok) global.neurolinkReady = null;
    return ok;
};

const getTTSAudio = async(text, speed, config) => {
    const axios = require('axios');
    const url = config.url || 'http://127.0.0.1:8002/koodo_tts';
    const baseUrl = url.replace(/\/koodo_tts\/?$/, '') + '/';

    // 就绪探测失败也继续往下走，避免服务端晚点起来时永远恢复不了。
    await ensureServer(axios, baseUrl);

    const payload = {
        refer_wav_path: config.refer_wav_path || '',
        // 注意：这里原来写的是 `config.prompt_text || "zh"`，那个 "zh" 是从
        // prompt_language 的默认值抄错过来的。一旦 refer_wav_path 被填上，
        // 参考文本就会变成 "zh"，和参考音频对不上，输出会严重劣化。
        prompt_text: config.prompt_text || '',
        prompt_language: config.prompt_language || 'zh',
        text: text,
        text_language: config.text_language || 'zh',
        cut_punc: config.cut_punc || '，。'
    };

    let attempts = 3;
    while (attempts > 0) {
        attempts--;
        try {
            const res = await axios.post(url, payload, {
                responseType: 'arraybuffer',
                timeout: 180000   // 以前没有超时，服务端一卡这个请求就永久挂起
            });
            return res.data;
        } catch (err) {
            const status = err.response && err.response.status;
            // 4xx 是请求本身的问题，重试多少次结果都一样。
            // 以前不分错误类型一律重试 30 次 x 2 秒 = 整整卡 60 秒才放弃。
            if (status && status >= 400 && status < 500) {
                console.log('Neurolink TTS: request rejected (HTTP ' + status + '), giving up.');
                return null;
            }
            console.log('Neurolink TTS: request failed (' + (status || err.code || err.message) + '), retries left: ' + attempts);
            if (attempts > 0) await new Promise(resolve => setTimeout(resolve, 1500));
        }
    }
    return null;
};

const getAudioPath = async(text, speed, dirPath, config) => {
    const fs = require('fs');
    const p = require('path');

    const ttsDir = p.join(dirPath, 'tts');
    if (!fs.existsSync(ttsDir)) {
        fs.mkdirSync(ttsDir, { recursive: true });
    }

    const audioData = await getTTSAudio(text, speed, config);

    // 长度为 0 的 Buffer / ArrayBuffer 在 JS 里是 truthy 的，所以原来的
    // `if (!audioData) return ""` 根本挡不住空响应，会写出一个播不响的 wav
    // （而且因为没有 HTTP 错误，重试逻辑也不会触发）。必须看字节数。
    const size = audioData ? (audioData.byteLength || audioData.length || 0) : 0;
    if (size < 1024) {
        console.log('Neurolink TTS: no usable audio (' + size + ' bytes), skipping.');
        return '';
    }

    // 原来用 new Date().getTime() 当文件名，Koodo 预取时同一毫秒会撞名
    fileSeq = (fileSeq + 1) % 1000000;
    const fileName = Date.now() + '_' + fileSeq + '.' + (config.voiceFormat || 'wav');
    const filePath = p.join(ttsDir, fileName);
    fs.writeFileSync(filePath, Buffer.from(audioData));
    return filePath;
};
global.getAudioPath = getAudioPath;
